void test_gimp_image_save_load(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *main_image;
  gchar *temp_filename;
  GimpImage *loaded_image;
  GError *error = NULL;

  main_image = create_test_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_return_if_fail(main_image != NULL);

  temp_filename = g_strdup_printf("/tmp/gimp_test_image_%d.xcf", getpid());

  if (!gimp_file_save(GIMP_FILE_SAVE, NULL, main_image, NULL, temp_filename, &error)) {
    g_printerr("Failed to save image: %s\n", error->message);
    g_clear_error(&error);
    g_free(temp_filename);
    g_object_unref(main_image);
    return;
  }

  loaded_image = gimp_file_load(GIMP_FILE_LOAD, NULL, temp_filename, NULL, &error);
  if (!loaded_image) {
    g_printerr("Failed to load image: %s\n", error->message);
    g_clear_error(&error);
    g_free(temp_filename);
    g_object_unref(main_image);
    return;
  }

  g_return_if_fail(loaded_image != NULL);

  g_object_unref(loaded_image);
  g_object_unref(main_image);

  g_unlink(temp_filename);
  g_free(temp_filename);
}

