void test_gimp_image_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar     *temp_path;
  GimpImage *loaded_image;
  GError    *error = NULL;
  gboolean   success;

  // Create main image
  image = gimp_image_new_with_parameters(gimp, 100, 100, GIMP_RGB, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  // Create temporary file path
  temp_path = g_strdup_printf("/tmp/test_image_%d.xcf", getpid());

  // Save image to temporary file
  success = gimp_image_save(image, "XCF", temp_path, &error);
  g_assert_no_error(error);
  g_assert(success);

  // Load image from temporary file
  loaded_image = gimp_image_load(temp_path, &error);
  g_assert_no_error(error);
  g_assert(loaded_image != NULL);

  // Verify image data integrity here (example placeholder)
  g_assert(gimp_image_get_width(image) == gimp_image_get_width(loaded_image));
  g_assert(gimp_image_get_height(image) == gimp_image_get_height(loaded_image));

  // Clean up
  gimp_image_delete(image);
  gimp_image_delete(loaded_image);
  g_unlink(temp_path);
  g_free(temp_path);
}

